Lemma srec_W_t48 : forall L (st : astate) (X : aconc) lo SP mb ms n nres hl iv,
  alayout_ok L -> sec_wf1 L (CSec mb ms n) -> srec_hl_ok L hl -> 0 <= nres -> 8 * nres <= 8388608 ->
  ATOP <= lo -> lo <= SP - 1024 ->
